begin;set local lock_timeout='3s';set local statement_timeout='30s';
lock table public.authors,public.works,public.editions,public.catalog_work_descriptions,public.catalog_edition_metadata in share row exclusive mode;
create temporary table catalog_release_receipt(seq integer,relation text,key jsonb,before_row jsonb,after_row jsonb) on commit drop;
do $release$ declare payload jsonb:='{"batch":"nl-scale-20261102-015","project":"qvplwejffhjvxaypmjut","actions":[{"ref":"w0","relation":"works","key":{"native_identity_key":"nlscale:20261102:ol:OL547745W"},"before":null,"after":{"title":"Bridget Jones''s Diary","author_id":1654,"first_publish_year":1996,"open_library_id":"OL547745W","cover_id":12692038,"source_type":"open_library","work_type":"novel","native_identity_key":"nlscale:20261102:ol:OL547745W"}},{"ref":"e0","relation":"editions","key":{"open_library_edition_id":"OL37788615M"},"before":null,"after":{"work_id":"@w0","open_library_edition_id":"OL37788615M","isbn_13":"9789053337264","isbn_10":null,"title":"Het dagboek van Bridget Jones","language":"dut","publisher":"Prometheus"}},{"ref":"d0","relation":"catalog_work_descriptions","key":{"work_id":"@w0","language":"nl"},"before":null,"after":{"work_id":"@w0","language":"nl","bound_author_id":1654,"text":"Bridget Jones houdt een jaar lang bij hoe zij haar leven als alleenstaande dertiger in Londen op orde probeert te krijgen. Ze schrijft over haar werk, haar familie en vrienden, maar ook over haar uiterlijk en de gewoonten die ze telkens wil veranderen. Romantische verwachtingen maken haar pogingen tot zelfverbetering ingewikkelder. In de dagboeknotities wisselen voornemens en dagelijkse teleurstellingen elkaar af. Helen Fielding laat zo zien hoe het beeld dat Bridget van een geslaagd leven heeft, botst met wat haar werkelijk overkomt.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.boekenzoeker.be/het-dagboek-van-bridget-jones","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p175816077"],"reference":"new-work-dossier-readings-015.json#8","checked_at":"2026-11-02T21:17:52.536Z","note":"First Bridget Jones novel1996, independently distinguished from existing Work3512/TheEdgeofReason1999. Canonical primary OL38952A is the exact Dutch edition credit and shares Q232359/ISNI/VIAF with exact-ISBN KB person. Sparse Work-author OL10352829A is not merged or deleted. German Goldmann9783442443925 remains excluded from Dutch proposal."},{"type":"original_substantive_source_review","sources":["https://www.boekenzoeker.be/het-dagboek-van-bridget-jones","https://www.boekenplatform.nl/isbn/9789053337264","https://www.booksinbelgium.be/nl/b/het-dagboek-van-bridget-jones-helen-fielding-9789053337264","https://openlibrary.org/works/OL547745W","https://www.sagaegmont.com/wp-content/uploads/2024/09/Saga_Nederlands_Kerstcatalogus_2022.pdf","https://data.bibliotheken.nl/id/nbt/p175816077"],"review":"content-amendment-007.json"},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","cover_id":12692038,"sha256":"416dd0769c9c75ebc727681ee434d98377f761819e35b02b36c8ef59b48a313a","reference":"cover-semantic-review-011.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-02T21:17:52.536Z","review_batch":"nl-scale-20261102-015"}},{"ref":"m0","relation":"catalog_edition_metadata","key":{"edition_id":"@e0"},"before":null,"after":{"edition_id":"@e0","work_id":"@w0","bound_author_id":1654,"bound_title":"Het dagboek van Bridget Jones","bound_language":"dut","bound_isbn13":"9789053337264","format":"paperback","cover_url":"https://covers.openlibrary.org/b/id/12692038-L.jpg?default=false","card_cover_url":"https://covers.openlibrary.org/b/id/12692038-M.jpg?default=false","evidence_url":"https://data.bibliotheken.nl/id/nbt/p175816077","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p175816077"],"reference":"new-work-dossier-readings-015.json#8","checked_at":"2026-11-02T21:17:52.536Z","note":"First Bridget Jones novel1996, independently distinguished from existing Work3512/TheEdgeofReason1999. Canonical primary OL38952A is the exact Dutch edition credit and shares Q232359/ISNI/VIAF with exact-ISBN KB person. Sparse Work-author OL10352829A is not merged or deleted. German Goldmann9783442443925 remains excluded from Dutch proposal."},{"type":"original_substantive_source_review","sources":["https://www.boekenzoeker.be/het-dagboek-van-bridget-jones","https://www.boekenplatform.nl/isbn/9789053337264","https://www.booksinbelgium.be/nl/b/het-dagboek-van-bridget-jones-helen-fielding-9789053337264","https://openlibrary.org/works/OL547745W","https://www.sagaegmont.com/wp-content/uploads/2024/09/Saga_Nederlands_Kerstcatalogus_2022.pdf","https://data.bibliotheken.nl/id/nbt/p175816077"],"review":"content-amendment-007.json"},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","cover_id":12692038,"sha256":"416dd0769c9c75ebc727681ee434d98377f761819e35b02b36c8ef59b48a313a","reference":"cover-semantic-review-011.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"review_status":"approved","reviewed_at":"2026-11-02T21:17:52.536Z","review_batch":"nl-scale-20261102-015"}},{"ref":"w1","relation":"works","key":{"native_identity_key":"nlscale:20261102:ol:OL14877880W"},"before":null,"after":{"title":"De profundis","author_id":32,"first_publish_year":null,"open_library_id":"OL14877880W","cover_id":6763411,"source_type":"open_library","work_type":null,"native_identity_key":"nlscale:20261102:ol:OL14877880W"}},{"ref":"e1","relation":"editions","key":{"open_library_edition_id":"OL24653181M"},"before":null,"after":{"work_id":"@w1","open_library_edition_id":"OL24653181M","isbn_13":"9789029003025","isbn_10":null,"title":"De profundis","language":"dut","publisher":"Meulenhoff"}},{"ref":"d1","relation":"catalog_work_descriptions","key":{"work_id":"@w1","language":"nl"},"before":null,"after":{"work_id":"@w1","language":"nl","bound_author_id":32,"text":"Vanuit de gevangenis schrijft Oscar Wilde een lange brief aan Alfred Douglas. Hij kijkt terug op hun verhouding en op de keuzes die zijn leven hebben getekend. Verwijt en verlangen naar verzoening staan naast beschouwingen over verlies, lijden en de betekenis van kunst. De persoonlijke aanleiding groeit zo uit tot een onderzoek van zijn eigen bestaan. De tekst laat een schrijver zien die probeert woorden te vinden voor wat hem is overkomen en voor een mogelijke toekomst daarna.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.dbnl.org/tekst/_med003mede01_01/_med003mede01_01_0435.php","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p089409639","https://data.bibliotheken.nl/id/nbt/p800008669"],"reference":"new-work-dossier-readings-015.json#95","checked_at":"2026-11-02T21:17:52.536Z","note":"Wilde’s prison letter, not a mixed prison-writings anthology. Lettermuseum bibliography explicitly identifies1971Komrij as first integral Dutch translation, Meulenhoffreeks18; exactISBN9789029003025 matches KB and merchant. Komrij is translator, not joint primary writer. Do not assign1905partial edition,1897writing,1949/1962full text or1971translation as an unqualified first-book year; leave optional year unknown pending bibliographic date choice. Researched non-fiction prison letter is outside the narrow Work-type field; explicit NULL retained, no schema or automatic taste classification change."},{"type":"original_substantive_source_review","sources":["https://www.dbnl.org/tekst/_med003mede01_01/_med003mede01_01_0435.php","https://www.deslegte.com/rotterdam/de-profundis-207624/","https://www.penguinrandomhouse.com/books/190550/de-profundis-by-oscar-wilde/","https://oscarwildesociety.co.uk/